// ../corpus-us-federal/dist/rules/ctc.js
var FROM6 = { effectiveFrom: "2025-01-01" };
var TY25_26 = { effectiveFrom: "2025-01-01", effectiveTo: "2027-01-01" };
var J9 = "us.federal";
var fact14 = (factId) => ({ kind: "fact", factId });
var money14 = (cents2) => ({ kind: "money", cents: cents2 });
var ruleRef12 = (ruleId) => ({ kind: "rule", ruleId });
var ctcRules = [
  {
    id: "us.federal.ctc.tentative",
    version: 3,
    // v2 predated the § 24(h)(4) $500 credit for other dependents
    jurisdiction: J9,
    title: "Child tax credit + credit for other dependents, before phase-out (as amended by OBBBA)",
    citation: {
      source: "26 U.S.C. \xA7 24(a), (h)(4), as amended by Pub. L. 119-21 (OBBBA) \xA7 70104; Rev. Proc. 2025-32 \xA7 4.05",
      section: "\xA7 24(a), (h)(2), (h)(4)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "The One Big Beautiful Bill Act (enacted July 4, 2025) raised the child tax credit to $2,200 per qualifying child for taxable years beginning in 2025; Rev. Proc. 2025-32 \xA7 4.05 confirms $2,200 for 2026. \xA7 24(h)(4): 'The credit determined under subsection (a) (after the application of paragraph (2)) shall be increased by $500 for each dependent of the taxpayer (as defined in section 152) other than a qualifying child' \u2014 unindexed, never refundable (the \xA7 24(d)(1)(A) ACTC cross-reference excludes it via (h)(5)'s per-child cap), subject to the same \xA7 24(b) phase-out as part of the combined credit (Schedule 8812 line 8). [\xA7 24(h)(4)(B) noncitizen exception and the dependent's TIN requirement (\xA7 24(e)) attested by the count.]"
    },
    ...TY25_26,
    output: { type: "money" },
    parameters: {
      perChild: { value: "220000", type: "money" },
      // $2,200
      perOtherDependent: { value: "50000", type: "money" }
      // $500, unindexed
    },
    formula: {
      kind: "add",
      args: [
        {
          kind: "mulInt",
          base: { kind: "param", name: "perChild" },
          count: fact14("qualifyingChildren")
        },
        {
          kind: "mulInt",
          base: { kind: "param", name: "perOtherDependent" },
          count: fact14("otherDependents")
        }
      ]
    }
  },
  {
    id: "us.federal.ctc.phaseout_threshold",
    version: 1,
    jurisdiction: J9,
    title: "CTC phase-out threshold by filing status",
    citation: {
      source: "26 U.S.C. \xA7 24(h)(3) (made permanent by Pub. L. 119-21 \xA7 70104)",
      section: "\xA7 24(h)(3)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "\u2026subsection (b)(2) shall be applied by substituting '$400,000' for '$110,000' [joint returns] and '$200,000' for the [other] amounts\u2026"
    },
    ...FROM6,
    output: { type: "money" },
    formula: {
      kind: "match",
      on: fact14("filingStatus"),
      cases: [
        // $400,000 applies only "in the case of a joint return" — every
        // other status (including QSS and MFS) gets $200,000.
        { when: "mfj", value: money14("40000000") },
        // $400,000
        { when: "single", value: money14("20000000") },
        // $200,000
        { when: "hoh", value: money14("20000000") },
        // $200,000
        { when: "mfs", value: money14("20000000") },
        // $200,000
        { when: "qss", value: money14("20000000") }
        // $200,000
      ]
    }
  },
  {
    id: "us.federal.ctc.reduction",
    version: 1,
    jurisdiction: J9,
    title: "CTC phase-out reduction",
    citation: {
      source: "26 U.S.C. \xA7 24(b)(1), (2)",
      section: "\xA7 24(b)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "\u2026reduced (but not below zero) by $50 for each $1,000 (or fraction thereof) by which the taxpayer's modified adjusted gross income exceeds the threshold amount."
    },
    ...FROM6,
    output: { type: "money" },
    parameters: {
      perStep: { value: "5000", type: "money" }
      // $50
    },
    formula: {
      kind: "mulInt",
      base: { kind: "param", name: "perStep" },
      count: {
        kind: "stepUnits",
        value: {
          kind: "max0",
          arg: {
            kind: "sub",
            left: ruleRef12("us.federal.agi"),
            right: ruleRef12("us.federal.ctc.phaseout_threshold")
          }
        },
        unitCents: "100000",
        // $1,000
        mode: "ceil"
        // "or fraction thereof"
      }
    }
  },
  {
    id: "us.federal.ctc.after_phaseout",
    version: 1,
    jurisdiction: J9,
    title: "Child tax credit after phase-out (before the liability limit)",
    citation: {
      source: "26 U.S.C. \xA7 24(a), (b)",
      section: "\xA7 24(a)\u2013(b)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "\u2026credit\u2026 reduced (but not below zero) by $50 for each $1,000 (or fraction thereof) by which\u2026 modified adjusted gross income exceeds the threshold amount."
    },
    ...FROM6,
    output: { type: "money" },
    formula: {
      kind: "max0",
      arg: {
        kind: "sub",
        left: ruleRef12("us.federal.ctc.tentative"),
        right: ruleRef12("us.federal.ctc.reduction")
      }
    }
  },
  {
    id: "us.federal.ctc",
    version: 6,
    // v5 predated the Schedule R credit ahead of it in the ordering
    jurisdiction: J9,
    title: "Child tax credit + ODC (nonrefundable portion, after other Schedule 3 credits)",
    citation: {
      source: "26 U.S.C. \xA7 24; \xA7 26(a); Schedule 8812 Credit Limit Worksheet",
      section: "\xA7 24(a)\u2013(b); \xA7 26(a)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "credit\u2026 limited to tax liability under \xA7 26(a) reduced by the other nonrefundable credits (the Schedule 8812 Credit Limit Worksheet subtracts Schedule 3 credits \u2014 here the \xA7 21 dependent-care, \xA7 25A education, \xA7 25B saver's, \xA7 23 adoption, and \xA7 22 Schedule R credits \u2014 before limiting the CTC); the refundable additional child tax credit (\xA7 24(d)) is computed separately."
    },
    ...FROM6,
    output: { type: "money" },
    formula: {
      kind: "min",
      args: [
        ruleRef12("us.federal.ctc.after_phaseout"),
        {
          kind: "max0",
          arg: {
            kind: "sub",
            left: {
              kind: "add",
              args: [
                ruleRef12("us.federal.income_tax_before_credits"),
                ruleRef12("us.federal.amt")
              ]
            },
            right: {
              kind: "add",
              args: [
                ruleRef12("us.federal.cdcc"),
                ruleRef12("us.federal.education.nonrefundable"),
                ruleRef12("us.federal.savers_credit"),
                ruleRef12("us.federal.adoption.nonrefundable"),
                ruleRef12("us.federal.schedule_r_credit")
              ]
            }
          }
        }
      ]
    }
  },
  {
    id: "us.federal.actc",
    version: 3,
    // v2 predated the Schedule C net-loss reduction of earned income
    jurisdiction: J9,
    title: "Additional child tax credit \u2014 refundable (simplified: 3+-child SS-tax alternative not modeled)",
    citation: {
      source: "26 U.S.C. \xA7 24(d), (h)(5); Rev. Proc. 2024-40 \xA7 2.05 / Rev. Proc. 2025-32 \xA7 4.05",
      section: "\xA7 24(d)(1); \xA7 24(h)(5)",
      url: "https://www.law.cornell.edu/uscode/text/26/24",
      excerpt: "The credit is refundable up to $1,700 per qualifying child (2025 and 2026, as adjusted), limited to 15 percent of so much of earned income as exceeds $2,500, and to the portion of the credit not used against tax. [The \xA7 24(d)(1)(B)(ii) alternative for taxpayers with 3+ children (social security taxes minus EIC) is NOT modeled \u2014 it can only increase the refund at very low earned income; disclosed. Earned income approximated as wages.]"
    },
    ...FROM6,
    output: { type: "money" },
    parameters: {
      refundableCapPerChild: { value: "170000", type: "money" },
      // $1,700
      earnedIncomeFloor: { value: "250000", type: "money" }
      // $2,500
    },
    formula: {
      kind: "min",
      args: [
        // the part of the credit the liability limit left unused
        {
          kind: "max0",
          arg: {
            kind: "sub",
            left: ruleRef12("us.federal.ctc.after_phaseout"),
            right: ruleRef12("us.federal.ctc")
          }
        },
        // refundable cap: $1,700 per qualifying child
        {
          kind: "mulInt",
          base: { kind: "param", name: "refundableCapPerChild" },
          count: fact14("qualifyingChildren")
        },
        // 15% of earned income (wages + SE earnings net of ½ SE tax) above $2,500
        {
          kind: "mulRate",
          base: {
            kind: "max0",
            arg: {
              kind: "sub",
              left: {
                kind: "add",
                args: [
                  fact14("wages"),
                  {
                    kind: "max0",
                    arg: {
                      kind: "sub",
                      left: fact14("selfEmploymentNetProfit"),
                      right: ruleRef12("us.federal.se_tax_half_deduction")
                    }
                  }
                ]
              },
              right: {
                kind: "add",
                args: [
                  { kind: "param", name: "earnedIncomeFloor" },
                  // Schedule C net loss reduces § 24(d) earned income too
                  fact14("scheduleCNetLoss")
                ]
              }
            }
          },
          rate: { num: "15", den: "100" },
          round: "half-up"
        }
      ]
    }
  },
  {
    id: "us.federal.income_tax_after_credits",
    version: 5,
    // v4 predated the Schedule R credit
    jurisdiction: J9,
    title: "Income tax after nonrefundable credits (CDCC + education + saver's + adoption + Schedule R + CTC/ODC)",
    citation: {
      source: "26 U.S.C. \xA7 26(a)",
      section: "\xA7 26(a)",
      url: "https://www.law.cornell.edu/uscode/text/26/26",
      excerpt: "The aggregate amount of credits allowed by this subpart\u2026 shall not exceed the taxpayer's regular tax liability for the taxable year\u2026 [modeled nonrefundable credits, in the forms' worksheet order: \xA7 21 dependent care, \xA7 25A education, \xA7 25B saver's, \xA7 23 adoption (nonrefundable portion), \xA7 24 child tax credit + credit for other dependents]."
    },
    ...FROM6,
    output: { type: "money" },
    formula: {
      kind: "max0",
      arg: {
        kind: "sub",
        left: {
          kind: "add",
          args: [
            ruleRef12("us.federal.income_tax_before_credits"),
            ruleRef12("us.federal.amt")
            // Schedule 2 line 1 joins line 16 before credits
          ]
        },
        right: {
          kind: "add",
          args: [
            ruleRef12("us.federal.cdcc"),
            ruleRef12("us.federal.education.nonrefundable"),
            ruleRef12("us.federal.savers_credit"),
            ruleRef12("us.federal.adoption.nonrefundable"),
            ruleRef12("us.federal.schedule_r_credit"),
            ruleRef12("us.federal.ctc")
          ]
        }
      }
    }
  }
];

// ../corpus-us-federal/dist/rules/dependents.js
var fact15 = (factId) => ({ kind: "fact", factId });
var intLit = (n) => ({ kind: "int", value: n });
var FROM7 = { effectiveFrom: "2025-01-01" };
var CITE_URL = "https://www.law.cornell.edu/uscode/text/26/152";
var ageTest = {
  kind: "or",
  args: [
    fact15("depPermanentlyDisabled"),
    {
      kind: "and",
      args: [
        fact15("depYoungerThanTaxpayer"),
        {
          kind: "or",
          args: [
            { kind: "cmp", op: "lt", left: fact15("depAge"), right: intLit("19") },
            {
              kind: "and",
              args: [
                fact15("depIsFullTimeStudent"),
                { kind: "cmp", op: "lt", left: fact15("depAge"), right: intLit("24") }
              ]
            }
          ]
        }
      ]
    }
  ]
};
function qualifyingRelativeRule(version, effectiveFrom, effectiveTo, limitCents, yearLabel, revProc) {
  return {
    id: "us.federal.dependent.qualifying_relative",
    version,
    jurisdiction: "us.federal",
    title: `Candidate is a qualifying relative (\xA7 152(d), TY${yearLabel})`,
    citation: {
      source: `26 U.S.C. \xA7 152(d); ${revProc}`,
      section: "\xA7 152(d)(1)",
      url: CITE_URL,
      excerpt: `\u2026an individual who bears a \xA7 152(d)(2) relationship to the taxpayer (or is a full-year member of the household), whose gross income for the calendar year is less than the exemption amount (TY${yearLabel}: as adjusted), with respect to whom the taxpayer provides over one-half of the individual's support, and who is not a qualifying child of the taxpayer or any other taxpayer. [Multiple-support agreements (\xA7 152(d)(3)) not modeled.]`
    },
    effectiveFrom,
    effectiveTo,
    output: { type: "bool" },
    parameters: {
      grossIncomeLimit: { value: limitCents, type: "money" }
    },
    formula: {
      kind: "and",
      args: [
        { kind: "not", arg: fact15("depIsQualifyingChildOfAnother") },
        fact15("depRelationshipRelative"),
        {
          kind: "cmp",
          op: "lt",
          left: fact15("depGrossIncome"),
          right: { kind: "param", name: "grossIncomeLimit" }
        },
        fact15("taxpayerProvidedOverHalfSupport")
      ]
    }
  };
}
var dependentRules = [
  {
    id: "us.federal.dependent.qualifying_child",
    version: 1,
    jurisdiction: "us.federal",
    title: "Candidate is a qualifying child (\xA7 152(c))",
    citation: {
      source: "26 U.S.C. \xA7 152(c)",
      section: "\xA7 152(c)(1)\u2013(3)",
      url: CITE_URL,
      excerpt: "\u2026a child of the taxpayer or a descendant of such a child, or a brother, sister, stepbrother, or stepsister\u2026 or a descendant; who has the same principal place of abode as the taxpayer for more than one-half of the taxable year; who is younger than the taxpayer and has not attained age 19 (24 if a full-time student), or is permanently and totally disabled; who has not provided over one-half of such individual's own support; and who has not filed a joint return. [Tie-breakers (\xA7 152(c)(4)) and divorced-parent rules (\xA7 152(e)) not modeled.]"
    },
    ...FROM7,
    output: { type: "bool" },
    formula: {
      kind: "and",
      args: [
        fact15("depRelationshipChild"),
        ageTest,
        fact15("depLivedWithTaxpayerOverHalfYear"),
        { kind: "not", arg: fact15("depProvidedOwnSupportOverHalf") },
        { kind: "not", arg: fact15("depFilesJointReturn") }
      ]
    }
  },
  qualifyingRelativeRule(1, "2025-01-01", "2026-01-01", "520000", "2025", "Rev. Proc. 2024-40 \xA7 2.24 ($5,200)"),
  qualifyingRelativeRule(2, "2026-01-01", "2027-01-01", "530000", "2026", "Rev. Proc. 2025-32 \xA7 4.23 ($5,300)"),
  ...[
    { version: 1, from: "2025-01-01", to: "2026-01-01", limit: "520000", year: "2025", revProc: "Rev. Proc. 2024-40 \xA7 2.24 ($5,200)" },
    { version: 2, from: "2026-01-01", to: "2027-01-01", limit: "530000", year: "2026", revProc: "Rev. Proc. 2025-32 \xA7 4.23 ($5,300)" }
  ].map(({ version, from, to, limit, year, revProc }) => ({
    id: "us.federal.dependent.qualifying_relative.multiple_support",
    version,
    jurisdiction: "us.federal",
    title: `Multiple-support agreement: over-10% contributor treated as providing over half (\xA7 152(d)(3), TY${year})`,
    citation: {
      source: `26 U.S.C. \xA7 152(d)(3); Form 2120; ${revProc}`,
      section: "\xA7 152(d)(3)",
      url: CITE_URL,
      excerpt: "\u2026the taxpayer shall be treated as having contributed over one-half of the support of an individual if no one person contributed over one-half, over one-half was received from two or more persons each of whom (but for the support test) could claim the individual, the taxpayer contributed over 10 percent, and every other over-10% contributor files a written declaration waiving the claim (Form 2120). [The group conditions and waivers are attested by the hasMultipleSupportAgreement fact \u2014 disclosed.]"
    },
    effectiveFrom: from,
    effectiveTo: to,
    output: { type: "bool" },
    applicability: fact15("hasMultipleSupportAgreement"),
    parameters: {
      grossIncomeLimit: { value: limit, type: "money" }
    },
    formula: {
      kind: "and",
      args: [
        { kind: "not", arg: fact15("depIsQualifyingChildOfAnother") },
        fact15("depRelationshipRelative"),
        {
          kind: "cmp",
          op: "lt",
          left: fact15("depGrossIncome"),
          right: { kind: "param", name: "grossIncomeLimit" }
        },
        // § 152(d)(3) replaces the over-half support test with over-10%
        fact15("taxpayerProvidedOver10PercentSupport")
      ]
    },
    overrides: { ruleId: "us.federal.dependent.qualifying_relative", priority: 10 }
  })),
  {
    id: "us.federal.dependent.qualifying_child.divorced_release",
    version: 1,
    jurisdiction: "us.federal",
    title: "Divorced or separated parents: the Form 8332 release reallocates the qualifying child (\xA7 152(e))",
    citation: {
      source: "26 U.S.C. \xA7 152(e); Form 8332",
      section: "\xA7 152(e)(1), (2)",
      url: CITE_URL,
      excerpt: "\u2026a child shall be treated as the qualifying child of the NONCUSTODIAL parent if the custodial parent signs a written declaration that such parent will not claim such child as a dependent (Form 8332) \u2014 provided the parents are divorced, separated, or lived apart during the last 6 months, the child received over one-half of support from the parents, and was in the custody of one or both for more than one-half of the year (attested by the depDivorcedParentsRule fact). The releasing CUSTODIAL parent correspondingly cannot claim the child. [\xA7 152(e) moves the DEPENDENCY (CTC); the EITC residency test is unaffected by a release \u2014 disclosed.]"
    },
    ...FROM7,
    output: { type: "bool" },
    applicability: fact15("depDivorcedParentsRule"),
    formula: {
      kind: "if",
      cond: fact15("taxpayerIsCustodialParent"),
      // custodial parent: normal tests, but a signed release forfeits the claim
      then: {
        kind: "and",
        args: [
          { kind: "not", arg: fact15("custodialParentReleasedClaim") },
          fact15("depRelationshipChild"),
          ageTest,
          fact15("depLivedWithTaxpayerOverHalfYear"),
          { kind: "not", arg: fact15("depProvidedOwnSupportOverHalf") },
          { kind: "not", arg: fact15("depFilesJointReturn") }
        ]
      },
      // noncustodial parent: the release stands in for the residency test
      else: {
        kind: "and",
        args: [
          fact15("custodialParentReleasedClaim"),
          fact15("depRelationshipChild"),
          ageTest,
          { kind: "not", arg: fact15("depFilesJointReturn") }
        ]
      }
    },
    overrides: { ruleId: "us.federal.dependent.qualifying_child", priority: 10 }
  },
  {
    id: "us.federal.dependent.is_dependent",
    version: 1,
    jurisdiction: "us.federal",
    title: "Candidate can be claimed as the taxpayer's dependent (\xA7 152(a))",
    citation: {
      source: "26 U.S.C. \xA7 152(a)",
      section: "\xA7 152(a)",
      url: CITE_URL,
      excerpt: "\u2026the term 'dependent' means a qualifying child, or a qualifying relative. [\xA7 152(b) taxpayer-side limits (dependents of dependents, married dependents filing jointly, non-citizens) not modeled \u2014 disclosed.]"
    },
    ...FROM7,
    output: { type: "bool" },
    formula: {
      // qualifying-child first: if it holds, none of the relative-test
      // facts (income, support) are ever demanded
      kind: "or",
      args: [
        { kind: "rule", ruleId: "us.federal.dependent.qualifying_child" },
        { kind: "rule", ruleId: "us.federal.dependent.qualifying_relative" }
      ]
    }
  }
];

// ../corpus-us-federal/dist/rules/education-credits.js
var J10 = "us.federal";
var FROM8 = { effectiveFrom: "2025-01-01" };
var fact16 = (factId) => ({ kind: "fact", factId });
