  max: [664, 4427, 7316, 8231],
  thresholdOther0: 10860,
  thresholdMFJ0: 18140,
  thresholdOtherKids: 23890,
  thresholdMFJKids: 31160,
  completedOther0: 19540,
  completedMFJ0: 26820,
  investmentLimit: 12200
