// ../corpus-us-federal/dist/rules/passive-losses.js
var J22 = "us.federal";
var fact31 = (factId) => ({ kind: "fact", factId });
var money28 = (cents2) => ({ kind: "money", cents: cents2 });
var ruleRef26 = (ruleId) => ({ kind: "rule", ruleId });
var zero19 = money28("0");
