// ../corpus-us-federal/dist/rules/schedule-d.js
var J25 = "us.federal";
var FROM15 = { effectiveFrom: "2025-01-01" };
var fact34 = (factId) => ({ kind: "fact", factId });
var money31 = (cents2) => ({ kind: "money", cents: cents2 });
